"""Fixture support: an independent KTEST v3 writer for the test suite.

The numbering walk below is written directly from the documented convention so
that it cross-checks ``eywa.oracles.HarnessLayout`` rather than reusing it.
"""

import base64
import struct


def int_width(bits):
    for candidate in (1, 2, 4, 8):
        if bits <= 8 * candidate:
            return candidate
    raise ValueError('unsupported bit width ' + repr(bits))


def u32(value):
    return struct.pack('>I', value)


def blob(data):
    if isinstance(data, str):
        data = data.encode('latin-1')
    return u32(len(data)) + data


def encode(objects, args=(), symbolic=(0, 0), version=3, magic=b'KTEST',
           trailing=b''):
    """Serialise ``[(name, data)]`` pairs into a base64 KTEST v3 payload."""
    out = bytearray(magic)
    out += u32(version)
    out += u32(len(args))
    for argument in args:
        out += blob(argument)
    out += u32(symbolic[0])
    out += u32(symbolic[1])
    out += u32(len(objects))
    for name, data in objects:
        out += blob(name)
        out += blob(data)
    out += trailing
    return base64.b64encode(bytes(out)).decode('ascii')


def leaf(value, width):
    return int(value).to_bytes(width, 'little')


class Builder(object):
    """Reserves harness identifiers exactly as the toolkit's MainBuilder does."""

    def __init__(self, types):
        self.types = {item['name']: item for item in types}
        self.number = 0
        self.objects = []

    def reserve(self):
        name = 'x%d' % self.number
        self.number += 1
        return name

    def emit(self, value, width):
        self.objects.append((self.reserve(), leaf(value, width)))

    def walk(self, type_name, value):
        definition = self.types[type_name]
        kind = definition['kind']
        if kind == 'alias':
            return self.walk(definition['target'], value)
        if kind == 'void':
            return
        if kind == 'bool':
            self.emit(1 if value else 0, 1)
        elif kind == 'char':
            self.emit(ord(value), 1)
        elif kind == 'int':
            self.emit(value, int_width(definition['bits']))
        elif kind == 'enum':
            self.emit(definition['values'].index(value), 4)
        elif kind == 'string':
            self.reserve()  # the character buffer owns no object
            for byte in value:
                self.emit(byte, 1)
        elif kind == 'array':
            self.reserve()  # the array itself owns no object
            for item in value:
                self.walk(definition['element'], item)
        elif kind == 'struct':
            self.reserve()  # the struct itself owns no object
            for field_name, field_type in definition['fields']:
                self.walk(field_type, value[field_name])
        else:
            raise ValueError('unknown kind ' + repr(kind))


def build(types, module, params, result=None, flag=None):
    """Build the object list of one record for ``module``."""
    builder = Builder(types)
    for name, type_name in module['params']:
        builder.walk(type_name, params[name])
    if result is not None:
        result_type = {item['name']: item for item in types}[module['result'][1]]
        if result_type['kind'] != 'void':
            builder.walk(module['result'][1], result)
    if flag is not None:
        builder.emit(1 if flag else 0, 1)
    return builder.objects, builder.number


def record(types, module, params, result=None, flag=None, **kwargs):
    objects, count = build(types, module, params, result, flag)
    return encode(objects, **kwargs), count
PYEOF
